import{_ as r,o,c as e,a2 as d}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"机器人","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/bot.md","filePath":"zh/guides/bot.md","lastUpdated":1788855895000}'),a={name:"zh/guides/bot.md"};function s(n,t,i,l,g,h){return o(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="机器人" tabindex="-1">机器人 <a class="header-anchor" href="#机器人" aria-label="Permalink to &quot;机器人&quot;">​</a></h1><p>机器人是 Memoh 里<strong>独立</strong>的智能体：自带 workspace、长期记忆、可配性格，并能通过各 <strong>渠道</strong> 对话、用工具做事。</p><h2 id="创建" tabindex="-1">创建 <a class="header-anchor" href="#创建" aria-label="Permalink to &quot;创建&quot;">​</a></h2><ol><li>侧栏进入 <strong>Bots</strong>。</li><li>点 <strong>Create Bot</strong>。</li><li>基本信息： <ul><li><strong>Display Name</strong>：对外的名字</li><li><strong>Avatar</strong>：头像 URL</li><li><strong>Timezone</strong>：可空；不填则继承用户或系统时区</li><li><strong>ACL Preset</strong>：如 <code>allow_all</code> 只给自己用、<code>private_only</code> 等快捷策略</li></ul></li><li>创建。</li></ol><hr><h2 id="详情页" tabindex="-1">详情页 <a class="header-anchor" href="#详情页" aria-label="Permalink to &quot;详情页&quot;">​</a></h2><p>点卡片进 <strong>详情</strong>，各 tab 管不同事：</p><table tabindex="0"><thead><tr><th>Tab</th><th>内容</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>workspace runtime、库、渠道、记忆等健康检查</td></tr><tr><td><strong>General</strong></td><td>主模型/标题/生图、记忆/搜索/浏览器/TTS、时区、语言、推理、危险区</td></tr><tr><td><strong>Desktop</strong></td><td>Workspace display runtime、有头浏览器、实时 display session</td></tr><tr><td><strong>Computers</strong></td><td>远程运行时（运行 Memoh runtime 的自有机器），机器人可在其上读写文件、执行命令</td></tr><tr><td><strong>Workspace</strong></td><td>容器型 workspace 起停、快照、导入导出</td></tr><tr><td><strong>Network</strong></td><td>Workspace 网络与 overlay provider 状态/动作</td></tr><tr><td><strong>Memory</strong></td><td>浏览、搜、建、改、压记忆</td></tr><tr><td><strong>Platforms</strong></td><td>各消息渠道（Telegram、Discord、飞书等）</td></tr><tr><td><strong>Access</strong></td><td>ACL 与默认通过/拒绝</td></tr><tr><td><strong>Tool Approval</strong></td><td>需要人类确认的工具审批设置</td></tr><tr><td><strong>Agents</strong></td><td>可为聊天 workspace 启用的 ACP 兼容编码智能体，如 Codex、Claude Code</td></tr><tr><td><strong>Email</strong></td><td>邮服绑定、发件箱</td></tr><tr><td><strong>Connectors</strong></td><td>经 Connect-It 连接的第三方服务（OAuth 或 API Key）：状态、启停、重新授权、断开</td></tr><tr><td><strong>Hooks</strong></td><td>保存在 <code>/data/.memoh/hooks.json</code> 的机器人自动化规则</td></tr><tr><td><strong>MCP</strong></td><td>连接（Stdio/Remote/OAuth）</td></tr><tr><td><strong>Compaction</strong></td><td>会话压缩设置与记录</td></tr><tr><td><strong>Schedule</strong></td><td>cron 与日志</td></tr><tr><td><strong>Skills</strong></td><td>技能 Markdown</td></tr></tbody></table><p>Files、Terminal、Display、Browser 这些 workspace 工具在聊天 workspace UI 里，不是机器人详情页 tab。要看文件、跑 shell、操作浏览器或桌面，请进入对应聊天里的 workspace 区域。</p><hr><h2 id="核心先配什么" tabindex="-1">核心先配什么 <a class="header-anchor" href="#核心先配什么" aria-label="Permalink to &quot;核心先配什么&quot;">​</a></h2><ol><li>打开机器人 <strong>General</strong>，先管模型与各类绑定。</li><li><strong>Schedule</strong> 管周期性自主任务。</li><li><strong>Compaction</strong> 管会话写不长时的压缩。</li><li><strong>Access</strong> 在 ACL 预设之后细调。</li></ol><p>若这些资源还没有，先建好：</p><ul><li><a href="/zh/integrations/providers/llm.html">供应商与模型</a></li><li><a href="/zh/integrations/providers/memory/builtin.html">内置记忆提供方</a>（如用）</li><li><a href="/zh/integrations/providers/web-search.html">搜索提供方</a></li><li><a href="/zh/integrations/providers/tts/index.html">TTS 提供方</a></li><li><a href="/zh/guides/acp.html">Agents / ACP</a></li></ul><hr><h2 id="general-字段" tabindex="-1">General 字段 <a class="header-anchor" href="#general-字段" aria-label="Permalink to &quot;General 字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Chat Model</strong></td><td>主对话模型</td></tr><tr><td><strong>Title Model</strong></td><td>可选，生成会话标题</td></tr><tr><td><strong>Image Generation Model</strong></td><td>可选，需带 <code>image-output</code> 的聊天模型</td></tr><tr><td><strong>Memory Provider</strong></td><td>长期记忆后端；内置类型还可自带记忆/向量模型</td></tr><tr><td><strong>Search Provider</strong></td><td>联网搜索用哪家</td></tr><tr><td><strong>TTS Model</strong></td><td>来自 TTS 流，不是普通 chat 供应商里选</td></tr><tr><td><strong>Timezone</strong></td><td>不填则用户时区再落到系统</td></tr><tr><td><strong>Language</strong></td><td>机器人主用语</td></tr><tr><td><strong>Reasoning Effort</strong></td><td>当前 chat 模型有 <code>reasoning</code> 时可用；可选值随模型而定（如 <code>low</code> / <code>medium</code> / <code>high</code>）</td></tr></tbody></table><p>注意：</p><ul><li><strong>生图模型</strong> 故意与主聊天模型分开，好单独换「更擅长出图」的。</li><li><strong>TTS</strong> 在 <a href="/zh/integrations/providers/tts/">TTS 提供方</a> 里用所配置语音提供方的 <code>speech</code> 模型。</li><li><code>context_window</code> 会影响状态栏展示和 <a href="/zh/guides/compaction.html">会话压缩</a> 的体感。</li></ul><hr><h2 id="compaction-相关-此处指「会话」" tabindex="-1">Compaction 相关（此处指「会话」） <a class="header-anchor" href="#compaction-相关-此处指「会话」" aria-label="Permalink to &quot;Compaction 相关（此处指「会话」）&quot;">​</a></h2><p>这里说的是 <strong>当前会话</strong> 的上下文压短，不是改记忆条目的那种。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Compaction Enabled</strong></td><td>是否自动在会话里压摘要</td></tr><tr><td><strong>Compaction Threshold</strong></td><td>触发的估算 token 阈值</td></tr><tr><td><strong>Compaction Ratio</strong></td><td>压多狠</td></tr><tr><td><strong>Compaction Model</strong></td><td>可选，专门做摘要的模型</td></tr></tbody></table><p>细节见 <a href="/zh/guides/compaction.html">会话上下文压缩</a>。</p><hr><h2 id="访问与-acl" tabindex="-1">访问与 ACL <a class="header-anchor" href="#访问与-acl" aria-label="Permalink to &quot;访问与 ACL&quot;">​</a></h2><p>创建时先给一个 <strong>ACL 预设</strong>，之后在 <strong>Access</strong> 里微调。<strong>预设</strong> 给一版默认策略，<strong>Default Effect</strong> 管「没命中规则时」放行还是挡。</p><p><a href="/zh/guides/sessions.html">会话</a> 与 Discuss 的默认行为在那一页。若你用 API/自动化，配置里还可能有 <code>discuss_probe_model_id</code> 等进阶项，日常创建不必先动。</p><hr><h2 id="workspace-文件与终端" tabindex="-1">Workspace 文件与终端 <a class="header-anchor" href="#workspace-文件与终端" aria-label="Permalink to &quot;Workspace 文件与终端&quot;">​</a></h2><p>Workspace 文件和终端在聊天 workspace UI 里使用；前提是该机器人有可用的 workspace runtime。这里可以：</p><ul><li>浏览、编辑 workspace 文件</li><li>打开 workspace 内的终端会话</li><li>在开启 display 后使用浏览器/桌面相关工具</li></ul><p>文件流程见 <a href="/zh/guides/files.html">文件</a>，有头浏览器和桌面操作见 <a href="/zh/guides/browser-computer-use.html">Browser / Computer Use</a>。</p><hr><h2 id="删除" tabindex="-1">删除 <a class="header-anchor" href="#删除" aria-label="Permalink to &quot;删除&quot;">​</a></h2><p><strong>General</strong> 最下 <strong>Danger Zone</strong> -&gt; <strong>Delete Bot</strong>，会删掉该机器人相关数据（含 workspace 文件与记忆等），<strong>不可恢复</strong>。</p>',36)])])}const m=r(a,[["render",s]]);export{p as __pageData,m as default};
